const blocks=[['Позиционирование','Понятно ли, кто вы, для кого и с какой задачей к вам идти','Новый читатель не должен собирать вас по кусочкам. Иван смотрит, понятны ли из описания и публикаций ваша роль, аудитория и задачи, с которыми вы помогаете.'],['Контентная система','Связаны ли публикации между собой или живут каждая своей жизнью','Хорошие посты — ещё не система. Важно, чтобы темы поддерживали друг друга и помогали читателю понять вашу работу, а не просто заполняли ленту.'],['Коммерческая часть','Понятно ли, что здесь можно получить, купить или заказать','Иван ищет понятное предложение и следующий шаг: что вы делаете, для кого это полезно и как обратиться. Продажи без игры «найди услугу по намёкам».'],['Доверие и отличимость','Есть ли причины остаться, доверять и запомнить именно вас','Кейсы, примеры, результаты и ваш собственный взгляд дают читателю опору. Иван смотрит, чем подтверждаются слова и почему запомнят именно вас.'],['Готовность к AI и автоматизации','Есть ли уже процессы, которые можно передать AI-помощнику','Сначала понятный процесс, потом автоматизация. Иван смотрит, есть ли повторяющиеся задачи, материалы и правила работы: помощнику тоже нужна инструкция, а не телепатия.']];
document.querySelector('#diagnostics').innerHTML=blocks.map((b,i)=>`<details><summary><span class="number">0${i+1}</span><strong>${b[0]}</strong><span class="sub">${b[1]}</span><span class="plus" aria-hidden="true">+</span></summary><p>${b[2]}</p></details>`).join('');
const zones=[{name:'Красная зона',color:'#b64d3c',tint:'#f2ddd4',title:'Сначала соберём основу',text:'Основа ещё не собрана: пока трудно понять, как здесь вообще всё устроено.',comment:'Похоже, у вас пока ещё сборка деталей, а не цельная конструкция.',tip:'Начните с простого: кто вы, кому помогаете и с какой задачей к вам можно прийти.'},{name:'Жёлтая зона',color:'#ad811f',tint:'#f3e8bc',title:'Детали есть. Пора их связать',text:'Сильные элементы уже есть, но они ещё не связаны в одну ясную систему.',comment:'Основа уже есть, но полки пока не подписаны. 😄',tip:'Свяжите темы публикаций с вашими предложениями и добавьте понятный следующий шаг.'},{name:'Зелёная зона',color:'#557454',tint:'#dde7d4',title:'Работает. Теперь настроим точнее',text:'Система уже работает, но в ней остаются отдельные разрывы и точки настройки.',comment:'Система уже работает. Теперь можно не только держать, но и усиливать.',tip:'Посмотрите на ответы «частично» и «нет»: там могут быть полезные точки настройки.'},{name:'Синяя зона',color:'#4e7898',tint:'#dce7ef',title:'Можно думать об усилении',text:'Всё уже собрано достаточно последовательно, и можно думать об усилении, масштабировании и автоматизации.',comment:'Похоже, вы уже думаете не только о контенте, но и о масштабировании.',tip:'Выберите один понятный повторяющийся процесс и подумайте, какую часть можно передать помощнику.'}];
const tabs=document.querySelector('.zone-tabs');tabs.innerHTML=zones.map((z,i)=>`<button type="button" class="zone-tab" id="zone-tab-${i}" role="tab" aria-controls="zone-panel" aria-selected="${i===0}" tabindex="${i===0?0:-1}" style="--color:${z.color};--tint:${z.tint}"><i aria-hidden="true"></i>${z.name}</button>`).join('');
function showZone(i){tabs.querySelectorAll('button').forEach((b,j)=>{b.setAttribute('aria-selected',String(i===j));b.tabIndex=i===j?0:-1});const z=zones[i],p=document.querySelector('#zone-panel');p.style.setProperty('--color',z.color);p.setAttribute('aria-labelledby',`zone-tab-${i}`);p.innerHTML=`<h3>${z.title}</h3><p>${z.text}</p>`}tabs.querySelectorAll('button').forEach((b,i)=>{b.addEventListener('click',()=>showZone(i));b.addEventListener('keydown',e=>{let n=i;if(e.key==='ArrowRight')n=(i+1)%4;else if(e.key==='ArrowLeft')n=(i+3)%4;else if(e.key==='Home')n=0;else if(e.key==='End')n=3;else return;e.preventDefault();showZone(n);tabs.children[n].focus()})});showZone(0);
const questions=['Новый человек быстро понимает, чем вы занимаетесь?','Из канала понятно, с какой задачей к вам можно прийти?','Контент связан с тем, что вы предлагаете?','Есть ли в канале реальные подтверждения работы: кейсы, результаты, примеры?','Понятно ли, что человеку делать дальше, если ему стало интересно?','Видно ли, какие процессы можно в будущем автоматизировать или передать помощнику?'];
document.querySelector('#quiz-questions').innerHTML=questions.map((q,i)=>`<fieldset><legend>${i+1}. ${q}</legend><div class="answers">${['Да','Частично','Нет'].map((a,j)=>`<label><input type="radio" name="q${i}" value="${2-j}" required><span>${a}</span></label>`).join('')}</div></fieldset>`).join('');
const form=document.querySelector('#quiz-form'),result=document.querySelector('#result'),submit=document.querySelector('#result-button');function update(){const count=form.querySelectorAll('input:checked').length;document.querySelector('#progress').value=count;document.querySelector('#progress-label').textContent=`Отвечено ${count} из 6`;submit.disabled=count!==6;submit.textContent=count===6?'Посмотреть мой результат':'Ответьте на все вопросы';result.hidden=true}form.addEventListener('change',update);form.addEventListener('reset',()=>setTimeout(update,0));function calculate(){const values=[...form.querySelectorAll('input:checked')].map(x=>Number(x.value));if(values.length!==6)throw new Error('Ответьте на все шесть вопросов');const score=values.reduce((a,b)=>a+b,0),index=score<=3?0:score<=7?1:score<=10?2:3,z=zones[index];result.style.setProperty('--color',z.color);result.style.setProperty('--tint',z.tint);result.innerHTML=`<p class="eyebrow">УСЛОВНЫЙ РЕЗУЛЬТАТ · ${score} ИЗ 12</p><h3>${z.name}</h3><p>${z.comment}</p><p>${z.tip}</p><p><b>Но настоящий Иван работает строже.</b> Он не верит вам на слово — ему подавай доказательства. 😄</p><p>Настоящая экспресс-диагностика строится не на галочках, а на реальных материалах канала.</p><details><summary style="display:block;padding:8px 0;font-size:12px">Как получился цвет?</summary><p style="padding:5px 0;font-size:12px">«Да» — 2 балла, «частично» — 1, «нет» — 0. Красная: 0–3, жёлтая: 4–7, зелёная: 8–10, синяя: 11–12. Это условная шкала демонстрации, а не методика настоящей диагностики.</p></details>`;result.hidden=false;return{zone:z.name,score,demonstration:true}}form.addEventListener('submit',e=>{e.preventDefault();calculate();result.focus();result.scrollIntoView({behavior:matchMedia('(prefers-reduced-motion: reduce)').matches?'instant':'smooth',block:'center'})});
document.querySelector('#next-story').addEventListener('click',function(){const panel=document.querySelector('#continuation');panel.hidden=!panel.hidden;this.setAttribute('aria-expanded',String(!panel.hidden));this.setAttribute('aria-controls','continuation')});
if(document.modelContext?.registerTool){try{Promise.resolve(document.modelContext.registerTool({name:'complete_ivan_demo',description:'Заполнить шесть ответов и показать условный результат демонстрации диагностики Ивана. Не настоящий аудит.',inputSchema:{type:'object',properties:{answers:{type:'array',items:{type:'integer',enum:[0,1,2]},minItems:6,maxItems:6}},required:['answers'],additionalProperties:false},annotations:{readOnlyHint:false},execute(input){if(!input||!Array.isArray(input.answers)||input.answers.length!==6||input.answers.some(v=>!Number.isInteger(v)||v<0||v>2))throw new Error('Нужно шесть ответов: 0, 1 или 2.');input.answers.forEach((v,i)=>{form.querySelector(`input[name="q${i}"][value="${v}"]`).checked=true});update();return calculate()}})).catch(()=>{})}catch{}}
